def json_tile_to_runtime(value: Any, label: str = "tile") -> tuple[int, int]:
    if not isinstance(value, list) or len(value) != 2 or not all(isinstance(item, int) for item in value):
        raise ValueError(f"{label} must be integer [row,col]")
    row, col = value
    return col, row


def runtime_tile_to_json(value: tuple[int, int]) -> list[int]:
    return [value[1], value[0]]


class ReadOnlyQueryEngine:
    def __init__(self, facts_path: Path = NORMAL_LOW_STAR_FACTS, evidence_path: Path = EVIDENCE_CONTEXT):
        facts = json.loads(facts_path.read_text(encoding="utf-8"))
        rows = facts.get("operators") if isinstance(facts, dict) else facts
        self.operators = {row["operator_id"]: row for row in rows}
        self.evidence = json.loads(evidence_path.read_text(encoding="utf-8"))
        self.range_transformer = ApproximateRealRangeTransformer()

    def _base(self, evidence_status: str) -> dict[str, Any]:
        return {
            "data_version": DATA_VERSION,
            "mechanics_version": MECHANICS_VERSION,
            "evidence_status": evidence_status,
            "applicability": "R8-1 ordinary-mode 1-3 star debug configuration under the current public runtime.",
            "unknowns": [],
        }

    def _operator(self, operator_id: str) -> dict[str, Any]:
        row = self.operators.get(operator_id)
        if row is None:
            raise ValueError(f"unknown operator {operator_id}")
        qualification = row.get("qualification") or {}
        if qualification.get("normal_mode") is not True or not 1 <= row["identity"]["rarity"] <= 3:
            raise ValueError(f"operator is outside ordinary 1-3 star domain: {operator_id}")
        return row

    def _declared_configuration_matches(self, row: dict[str, Any], declared: Any) -> bool:
        expected = row.get("debug_configuration")
        if not isinstance(expected, dict) or not isinstance(declared, dict):
            return False
        if row.get("qualification", {}).get("eligible_for_debug") is not True:
            return False
        if expected.get("legal_for_debug") is not True:
            return False
        required_keys = ["rarity", "phase_index", "level", "potential_level", "trust"]
        if expected.get("skill_level_index") is not None:
            required_keys.append("skill_level_index")
        if any(key not in declared for key in required_keys):
            return False
        if any(declared.get(key) != expected.get(key) for key in required_keys):
            return False
        derived_skill_rank = (
            None
            if expected.get("skill_level_index") is None
            else int(expected["skill_level_index"]) + 1
        )
        for key, value in (
            ("skill_level_index", expected.get("skill_level_index")),
            ("skill_rank", derived_skill_rank),
            ("required_potential_rank", expected.get("required_potential_rank")),
        ):
            if key in declared and declared.get(key) != value:
                return False
        return True

    def _skill(self, row: dict[str, Any]) -> dict[str, Any] | None:
        return (row.get("skills") or [None])[0]

from __future__ import annotations

from typing import Protocol


class RangeTransformer(Protocol):
    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        """Convert canonical range offsets into map tiles for one facing direction."""


class CanonicalSyntheticRangeTransformer:
    """Synthetic-only orientation rule; it makes no claim about Arknights' rule.

    Offsets are defined for RIGHT. RIGHT=(dx,dy), DOWN=(-dy,dx), LEFT=(-dx,-dy),
    and UP=(dy,-dx), with x increasing right and y increasing down.
    """

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported synthetic direction: {direction}")
        def rotate(dx: int, dy: int) -> tuple[int, int]:
            if direction == "RIGHT": return dx, dy
            if direction == "DOWN": return -dy, dx
            if direction == "LEFT": return -dx, -dy
            return dy, -dx
        return {(origin[0] + rotate(dx, dy)[0], origin[1] + rotate(dx, dy)[1]) for dx, dy in offsets}


class ApproximateRealRangeTransformer:
    """Real raw range cells in the fixture's bottom-left field coordinates."""

    _directions = {"RIGHT", "DOWN", "LEFT", "UP"}

    def covered_tiles(
        self,
        *,
        origin: tuple[int, int],
        offsets: tuple[tuple[int, int], ...],
        direction: str,
    ) -> set[tuple[int, int]]:
        if direction not in self._directions:
            raise ValueError(f"Unsupported real direction: {direction}")
        def rotate(row: int, col: int) -> tuple[int, int]:
            if direction == "RIGHT": return col, row
            if direction == "DOWN": return row, -col
            if direction == "LEFT": return -col, -row
            return -row, col
        return {
            (origin[0] + rotate(row, col)[0], origin[1] + rotate(row, col)[1])
            for row, col in offsets
        }

        if enemy.attack_stand_until > self._EPSILON and state.time + self._EPSILON >= enemy.attack_stand_until:
            self._emit(state, EventType.ATTACK_RECOVERY_END, source=enemy.instance_id)
            enemy.attack_stand_until = 0.0
        if (
            enemy.attack_windup > self._EPSILON
            and not enemy.attack_windup_started
            and state.time + self._EPSILON >= enemy.next_attack_time - enemy.attack_windup
        ):
            self._emit(state, EventType.ATTACK_WINDUP, source=enemy.instance_id)
            enemy.attack_windup_started = True
        if state.time + self._EPSILON < enemy.next_attack_time:
            continue
        target_id = enemy.blocked_by if enemy.blocked_by in state.deployed_operators else None
        protected_target = None
        if target_id is None:
            protected_target = self._target_protected_for(stage, state, enemy)
            if protected_target is not None:
                target_id = protected_target.instance_id
        if target_id is None and enemy.attack_range is not None:
            position = self._enemy_position(stage, enemy)
            candidates = [operator for operator in state.deployed_operators.values() if hypot(position[0] - operator.tile[0], position[1] - operator.tile[1]) <= enemy.attack_range + self._EPSILON]
            if candidates:
                target_id = min(candidates, key=lambda item: (hypot(position[0] - item.tile[0], position[1] - item.tile[1]), item.operator_id)).operator_id
        if target_id is None:
            enemy.attack_windup_started = state.time + self._EPSILON < enemy.next_attack_time
            continue
        special_ability = next(
            (
                ability for ability in enemy.abilities
                if ability.family == "EVERY_NTH_ATTACK"
                and ability.attack_count_threshold > 0
                and enemy.normal_attack_count + 1 >= ability.attack_count_threshold
            ),
            None,
        )
        self._emit(state, EventType.ATTACK_STRIKE, source=enemy.instance_id, target=target_id)
        self._emit(state, EventType.ATTACK_START, source=enemy.instance_id, target=target_id)
        if protected_target is not None:
            raw_damage = physical_damage(enemy.atk, protected_target.defense)
            self._damage_enemy(state, protected_target, enemy.instance_id, raw_damage, kind="enemy_physical")
        elif special_ability:
            self._emit(state, EventType.ENEMY_ABILITY_START, source=enemy.instance_id, ability=special_ability.ability_id, target_count=1)
            self._damage_operator(state, enemy, target_id, special_ability)
            self._emit(state, EventType.ENEMY_ABILITY_HIT, source=enemy.instance_id, target=target_id,
                       ability=special_ability.ability_id, amount=enemy.atk * special_ability.atk_scale,
                       kind=special_ability.damage_type)
            self._emit(state, EventType.ENEMY_STATUS_HIT, source=enemy.instance_id, target=target_id,
                       ability=special_ability.ability_id, status=special_ability.status_name,
                       duration=special_ability.status_duration, attack_speed_delta=special_ability.attack_speed_delta)
            operator = state.deployed_operators.get(target_id)
            if operator:
                operator.attack_speed_status_until = state.time + special_ability.status_duration
                operator.attack_speed_status_delta = special_ability.attack_speed_delta
            enemy.normal_attack_count = 0
        else:
            self._damage_operator(state, enemy, target_id)
            enemy.normal_attack_count += 1
        effective_attack_interval = enemy.attack_interval
        if enemy.attack_speed_status_until >= state.time:
            effective_attack_interval = enemy.attack_interval / (1.0 + enemy.attack_speed_status_delta / 100.0)
        enemy.next_attack_time = state.time + effective_attack_interval
        enemy.attack_stand_until = max(enemy.attack_stand_until, state.time + enemy.attack_recovery)
        enemy.attack_windup_started = False

def _advance_enemy_passives(self, state: SimulationState, dt: float) -> None:
    for enemy in tuple(state.active_enemies.values()):
        if enemy.hp_recovery_per_second <= 0.0 or enemy.max_hp <= 0.0 or enemy.hp >= enemy.max_hp:
            continue
        amount = min(enemy.hp_recovery_per_second * dt, enemy.max_hp - enemy.hp)
        enemy.hp += amount
        self._emit(state, EventType.HEAL, source=enemy.instance_id, target=enemy.instance_id,
                   amount=amount, reason="GAME_DATA_PASSIVE_HP_REGENERATION")

def _enemy_ability_outputs(self, state: SimulationState, stage: Stage, enemy: RuntimeEnemy,
                           pending_area_hits: list[_PendingAreaHit], pending_area_casts: list[_PendingAreaCast]) -> None:
    if not enemy.abilities:
        return
    if state.time + self._EPSILON < enemy.ability_next_fire_time:
        return
    for ability in enemy.abilities:
        if ability.family == "DELAYED_LOCKED_AREA_ATTACK":
            if enemy.area_hit_time is not None:
                continue
            position = self._enemy_position(stage, enemy)
            acquisition_radius = enemy.attack_range if enemy.attack_range is not None else ability.range_radius
            candidates: list[RuntimeEnemy] = [
                item for item in state.active_enemies.values()
                if item.is_neutral
                and hypot(position[0] - self._enemy_position(stage, item)[0],
                          position[1] - self._enemy_position(stage, item)[1]) <= acquisition_radius
            ] if ability.protected_target_priority else []
            if not candidates:
                candidates = [
                    operator for operator in state.deployed_operators.values()
                    if hypot(position[0] - operator.tile[0], position[1] - operator.tile[1]) <= acquisition_radius
                ]
            if not candidates:
                continue
            candidate = min(candidates, key=lambda item: getattr(item, "spawn_index", 0) if isinstance(item, RuntimeEnemy) else getattr(item, "operator_id"))
            cast_position = self._enemy_position(stage, candidate) if isinstance(candidate, RuntimeEnemy) else candidate.tile
            enemy.area_hit_time = state.time + ability.windup_seconds + ability.delay_seconds
            enemy.area_hit_radius = ability.range_radius
            self._emit(state, EventType.ENEMY_ABILITY_START, source=enemy.instance_id,
                       ability=ability.ability_id, target_position=cast_position,
                       windup_seconds=ability.windup_seconds, delay=ability.delay_seconds,
                       radius=ability.range_radius)
            enemy.ability_next_fire_time = state.time + ability.cooldown
            pending_area_casts.append(_PendingAreaCast(
                state.time + ability.windup_seconds, enemy.instance_id,
                candidate.instance_id if isinstance(candidate, RuntimeEnemy) else candidate.operator_id,
                isinstance(candidate, RuntimeEnemy), ability.delay_seconds,
                ability.range_radius, ability.atk_scale, ability.damage_type,
            ))
            continue
        if ability.family != "PERIODIC_AREA_ATTACK":
            continue
        position = self._enemy_position(stage, enemy)
        targets = [
            operator for operator in state.deployed_operators.values()
            if hypot(position[0] - operator.tile[0], position[1] - operator.tile[1]) <= ability.range_radius + self._EPSILON
        ]
        self._emit(state, EventType.ENEMY_ABILITY_START, source=enemy.instance_id, ability=ability.ability_id, target_count=len(targets))
        if not targets:
            break
        for target in sorted(targets, key=lambda item: item.operator_id):
            damage = (
                arts_damage(enemy.atk * ability.atk_scale, target.magic_resistance)
                if ability.damage_type == "ARTS" else physical_damage(enemy.atk * ability.atk_scale, target.defense)
            )
            target.hp -= damage
            self._emit(state, EventType.ENEMY_ABILITY_HIT, source=enemy.instance_id, target=target.operator_id,
                       ability=ability.ability_id, amount=damage, kind=ability.damage_type)
            if target.hp <= 0:
                self._remove_operator(state, target.operator_id, death=True)
        break
    if not any(ability.family == "DELAYED_LOCKED_AREA_ATTACK" for ability in enemy.abilities):
        enemy.ability_next_fire_time = state.time + max(ability.cooldown for ability in enemy.abilities)

def _process_area_cast(self, state: SimulationState, stage: Stage, cast: _PendingAreaCast,
                       pending_area_hits: list[_PendingAreaHit]) -> None:
    source = state.active_enemies.get(cast.source_id)
    if source is None or source.hidden:
        self._emit(state, EventType.ENEMY_ABILITY_CANCELLED, source=cast.source_id,
                   target=cast.target_id, reason="SOURCE_UNAVAILABLE")
        return
    candidate = (
        state.active_enemies.get(cast.target_id)
        if cast.target_is_neutral
        else state.deployed_operators.get(cast.target_id)
    )
    if candidate is None or (cast.target_is_neutral and candidate.hidden):
        self._emit(state, EventType.ENEMY_ABILITY_CANCELLED, source=cast.source_id,
                   target=cast.target_id, reason="TARGET_UNAVAILABLE_BEFORE_PROJECTILE_CREATION")
        if source.area_hit_time is not None and source.area_hit_time <= cast.time + cast.delay_seconds + self._EPSILON:
            source.area_hit_time = None
            source.area_hit_radius = None
        return
    locked_position = self._enemy_position(stage, candidate) if cast.target_is_neutral else candidate.tile
    source.area_hit_position = locked_position
    self._emit(state, EventType.PROJECTILE_BORN, source=cast.source_id, target=cast.target_id,
               locked_position=locked_position, delay=cast.delay_seconds, radius=cast.range_radius)
    pending_area_hits.append(_PendingAreaHit(
        cast.time + cast.delay_seconds, cast.source_id, locked_position,
        cast.range_radius, source.atk * cast.atk_scale, cast.damage_type,
    ))

def _process_area_hit(self, state: SimulationState, stage: Stage, hit: _PendingAreaHit) -> None:
    for enemy in tuple(state.active_enemies.values()):
        if not enemy.is_neutral:
            continue
        enemy_position = self._enemy_position(stage, enemy)
        if hypot(hit.position[0] - enemy_position[0], hit.position[1] - enemy_position[1]) > hit.radius + self._EPSILON:
            continue
        damage = (
            arts_damage(hit.damage, enemy.magic_resistance)
            if hit.damage_type == "ARTS"
            else hit.damage if hit.damage_type == "TRUE" else physical_damage(hit.damage, enemy.defense)
        )
        self._damage_enemy(state, enemy, hit.source_id, damage, kind=hit.damage_type)
    for operator in tuple(state.deployed_operators.values()):
        if hypot(hit.position[0] - operator.tile[0], hit.position[1] - operator.tile[1]) > hit.radius + self._EPSILON:
            continue
        damage = (
            arts_damage(hit.damage, operator.magic_resistance)
            if hit.damage_type == "ARTS" else physical_damage(hit.damage, operator.defense)
        )

    return (row.get("skills") or [None])[0]

def query_mechanic(self, arguments: dict[str, Any]) -> dict[str, Any]:
    topic = arguments.get("topic")
    if not isinstance(topic, str) or topic not in MECHANIC_TOPICS:
        return {**self._base("UNKNOWN"), "topic": topic, "status": "UNKNOWN", "result": None, "unknowns": ["topic is not in the whitelist"]}
    if topic == "coordinates_and_direction":
        result = {"json_tile": "[row,col]", "runtime_tile": "(x=col,y=row)", "conversion": "(col,row)", "legal_directions": ["UP", "DOWN", "LEFT", "RIGHT"]}
        sources = ["scripts/kimi_readonly_tools.py", "scripts/run_r8_1_low_star_full_tactical_closure_v1.py"]
        unknowns = []
    elif topic == "range_template":
        result = {"storage": "RIGHT-relative [row,col] offsets", "rotation_source": "src/arknights_planner/simulator/range.py", "transformer": "ApproximateRealRangeTransformer"}
        sources = ["data/ArknightsGameData/zh_CN/gamedata/excel/range_table.json", "src/arknights_planner/simulator/range.py"]
        unknowns = ["exact client orientation/geometric rounding is not independently verified here"]
    elif topic == "skill_sp_recovery_during_effect":
        result = {"supported_mode": "INCREASE_WITH_TIME", "recovery_while_active": False, "recovery_per_second": 1.0, "attack_sp_mode": "INCREASE_WHEN_ATTACK"}
        sources = ["src/arknights_planner/simulator/simulator.py", "src/arknights_planner/adapters/low_rarity_skill.py"]
        unknowns = ["exact client windup, integer rounding and SP timing are UNKNOWN"]
    elif topic == "current_damage_formula":
        result = {
            "physical": "max(0.05A, A-D)",
            "arts": "max(0.05A, 0.01A*(100-RES))",
            "attack_interval": "T0/(clamp(attackSpeed,10,600)/100)",
            "modifier_pipeline": "direct add, direct multiplier, final add, final multiplier",
        }
        sources = ["data/prts/game-data-basics.html", "data/prts/battle-mechanics.html", "src/arknights_planner/simulator/combat_rules.py"]
        unknowns = ["damage modifiers, talent effects and exact client rounding are outside this bounded formula"]
    elif topic == "r8_1_stage_facts":
        active = self.evidence.get("stage_active_facts") or {}
        result = {
            "stage_id": self.evidence.get("stage_id"),
